package com.abyzz.ankiskiller;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Thin synchronous client for AnkiConnect (https://foosoft.net/projects/anki-connect/),
 * which listens on http://localhost:8765 while Anki is open. Every method here runs a
 * blocking HTTP call, so call them off the client thread (the review scheduler thread is fine).
 *
 * Scheduling is entirely Anki's job. We never compute intervals; answerCards hands the ease
 * straight to Anki's SM-2 and the review syncs back to the desktop, no reviewer window needed.
 */
@Slf4j
public class AnkiConnect
{
	// 127.0.0.1, not "localhost": Java may resolve localhost to IPv6 ::1, but AnkiConnect
	// binds IPv4 only by default, so the ::1 attempt is refused and Anki looks unreachable.
	private static final String URL = "http://127.0.0.1:8765";
	private static final MediaType JSON = MediaType.get("application/json");
	private static final int VERSION = 6;

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	public AnkiConnect(OkHttpClient httpClient, Gson gson)
	{
		// Short timeouts so a closed Anki never hangs the UI thread that probes reachability.
		this.httpClient = httpClient.newBuilder()
			.connectTimeout(2, TimeUnit.SECONDS)
			.readTimeout(5, TimeUnit.SECONDS)
			.callTimeout(6, TimeUnit.SECONDS)
			.build();
		this.gson = gson;
	}

	public static class AnkiUnavailableException extends IOException
	{
		AnkiUnavailableException(String message, Throwable cause)
		{
			super(message, cause);
		}

		AnkiUnavailableException(String message)
		{
			super(message);
		}
	}

	/** True if AnkiConnect answered a version ping. Cheap reachability check for the panel. */
	public boolean isReachable()
	{
		try
		{
			version();
			return true;
		}
		catch (IOException e)
		{
			return false;
		}
	}

	public int version() throws IOException
	{
		return invoke("version", null).getAsInt();
	}

	public List<String> deckNames() throws IOException
	{
		List<String> decks = new ArrayList<>();
		for (JsonElement e : invoke("deckNames", null).getAsJsonArray())
		{
			decks.add(e.getAsString());
		}
		Collections.sort(decks);
		return decks;
	}

	/** Card ids that are due for review in the given deck, in Anki's own queue order. */
	public List<Long> findDueCards(String deck) throws IOException
	{
		JsonObject params = new JsonObject();
		// is:due covers review + learning cards that are ready; new cards are picked up too via deck limit.
		params.addProperty("query", "deck:\"" + deck + "\" (is:due OR is:new)");
		List<Long> ids = new ArrayList<>();
		for (JsonElement e : invoke("findCards", params).getAsJsonArray())
		{
			ids.add(e.getAsLong());
		}
		return ids;
	}

	/** Fetch the rendered question/answer for a single card. */
	public Card cardInfo(long cardId) throws IOException
	{
		JsonObject params = new JsonObject();
		JsonArray cards = new JsonArray();
		cards.add(cardId);
		params.add("cards", cards);

		JsonArray info = invoke("cardsInfo", params).getAsJsonArray();
		if (info.size() == 0)
		{
			throw new AnkiUnavailableException("cardsInfo returned nothing for " + cardId);
		}
		JsonObject c = info.get(0).getAsJsonObject();
		String questionHtml = c.get("question").getAsString();
		String answerHtml = backOnly(c.get("answer").getAsString());
		return new Card(cardId,
			stripHtml(questionHtml),
			stripHtml(answerHtml),
			extractImages(questionHtml),
			extractImages(answerHtml));
	}

	/**
	 * Review a card directly through Anki's scheduler. ease is 1..4 (Again..Easy).
	 * This is headless: Anki's reviewer does not need to be open on the card.
	 * Requires an AnkiConnect version that exposes the answerCards action.
	 */
	public void answerCard(long cardId, int ease) throws IOException
	{
		JsonObject answer = new JsonObject();
		answer.addProperty("cardId", cardId);
		answer.addProperty("ease", ease);
		JsonArray answers = new JsonArray();
		answers.add(answer);
		JsonObject params = new JsonObject();
		params.add("answers", answers);
		invoke("answerCards", params);
	}

	/** Core AnkiConnect call. Throws on transport failure or an error field in the response. */
	private JsonElement invoke(String action, JsonObject params) throws IOException
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("action", action);
		payload.addProperty("version", VERSION);
		if (params != null)
		{
			payload.add("params", params);
		}

		Request request = new Request.Builder()
			.url(URL)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.body() == null)
			{
				throw new AnkiUnavailableException("Empty response from AnkiConnect");
			}
			JsonObject body = gson.fromJson(response.body().string(), JsonObject.class);
			JsonElement error = body.get("error");
			if (error != null && !error.isJsonNull())
			{
				throw new IOException("AnkiConnect error: " + error.getAsString());
			}
			return body.get("result");
		}
		catch (IOException e)
		{
			if (e instanceof AnkiUnavailableException)
			{
				throw e;
			}
			throw new AnkiUnavailableException("Could not reach AnkiConnect at " + URL
				+ " (is Anki open with the AnkiConnect add-on installed?)", e);
		}
	}

	private static final Pattern IMG_SRC = Pattern.compile("(?i)<img[^>]+src=[\"']([^\"']+)[\"']");

	/** Pull any {@code <img>} media referenced in the HTML and fetch each from Anki as an image. */
	private List<BufferedImage> extractImages(String html)
	{
		List<BufferedImage> images = new ArrayList<>();
		if (html == null)
		{
			return images;
		}
		Matcher m = IMG_SRC.matcher(html);
		while (m.find())
		{
			String src = m.group(1);
			// Only fetch local Anki media; skip anything with a URL scheme (http, data, etc).
			if (src.matches("(?i)^[a-z][a-z0-9+.-]*:.*"))
			{
				continue;
			}
			try
			{
				BufferedImage img = retrieveMedia(decodeSrc(src));
				if (img != null)
				{
					images.add(img);
				}
			}
			catch (IOException e)
			{
				log.debug("Could not fetch media {}: {}", src, e.getMessage());
			}
		}
		return images;
	}

	/** Fetch one media file from Anki by filename, returning null if it does not exist. */
	private BufferedImage retrieveMedia(String filename) throws IOException
	{
		JsonObject params = new JsonObject();
		params.addProperty("filename", filename);
		JsonElement res = invoke("retrieveMediaFile", params);
		if (res == null || res.isJsonNull() || !res.isJsonPrimitive())
		{
			return null;
		}
		if (res.getAsJsonPrimitive().isBoolean())
		{
			return null; // AnkiConnect returns false when the file is missing.
		}
		byte[] bytes = Base64.getDecoder().decode(res.getAsString());
		return ImageIO.read(new ByteArrayInputStream(bytes));
	}

	private static String decodeSrc(String src)
	{
		if (src.indexOf('%') < 0)
		{
			return src;
		}
		try
		{
			return java.net.URLDecoder.decode(src, "UTF-8");
		}
		catch (Exception e)
		{
			return src;
		}
	}

	/**
	 * Anki's answer field is the rendered card back: the front, an {@code <hr id=answer>}
	 * divider, then the actual answer. Keep only the part after the divider so the answer
	 * doesn't just repeat the question. Falls back to the whole thing if there's no divider.
	 */
	private static String backOnly(String answerHtml)
	{
		if (answerHtml == null)
		{
			return "";
		}
		java.util.regex.Matcher m = java.util.regex.Pattern
			.compile("(?i)<hr\\s+id=\"?answer\"?[^>]*>")
			.matcher(answerHtml);
		if (m.find())
		{
			return answerHtml.substring(m.end());
		}
		return answerHtml;
	}

	/** Anki question/answer come back as HTML; reduce to plain text for the Swing/overlay UI. */
	private static String stripHtml(String html)
	{
		if (html == null)
		{
			return "";
		}
		return html
			.replaceAll("(?s)<style.*?</style>", "")
			.replaceAll("(?s)<script.*?</script>", "")
			.replaceAll("<[^>]+>", " ")
			.replace("&nbsp;", " ")
			.replace("&amp;", "&")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replaceAll("\\s+", " ")
			.trim();
	}
}

package com.abyzz.ankiskiller;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(AnkiSkillerConfig.GROUP)
public interface AnkiSkillerConfig extends Config
{
	String GROUP = "ankiskiller";

	// Non-visible keys used for persistence (managed programmatically, not shown in the panel).
	String KEY_TOTAL_XP = "totalXp";
	String KEY_CARDS_ANSWERED = "cardsAnswered";
	String KEY_SELECTED_DECK = "selectedDeck";

	@ConfigSection(
		name = "Review",
		description = "When cards appear and where",
		position = 0
	)
	String reviewSection = "review";

	@ConfigSection(
		name = "Popup",
		description = "Optional in-game popup card",
		position = 1
	)
	String popupSection = "popup";

	@ConfigSection(
		name = "Progress",
		description = "XP tuning",
		position = 2
	)
	String progressSection = "progress";

	@ConfigSection(
		name = "Display",
		description = "Text size",
		position = 3
	)
	String displaySection = "display";

	enum UiScale
	{
		P100("100%", 1.0),
		P125("125%", 1.25),
		P150("150%", 1.5),
		P175("175%", 1.75),
		P200("200%", 2.0);

		private final String label;
		private final double factor;

		UiScale(String label, double factor)
		{
			this.label = label;
			this.factor = factor;
		}

		public double getFactor()
		{
			return factor;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "uiScale",
		name = "Text size",
		description = "Scale the plugin's panel text and popup. Increase this if it looks too small at your resolution.",
		section = "display",
		position = 0
	)
	default UiScale uiScale()
	{
		return UiScale.P100;
	}

	// ---- Review ----

	enum ReviewInterval
	{
		ONE_MINUTE("1 minute", 1),
		FIVE_MINUTES("5 minutes", 5),
		TEN_MINUTES("10 minutes", 10),
		FIFTEEN_MINUTES("15 minutes", 15),
		THIRTY_MINUTES("30 minutes", 30),
		CUSTOM("Custom", -1);

		private final String label;
		private final int minutes;

		ReviewInterval(String label, int minutes)
		{
			this.label = label;
			this.minutes = minutes;
		}

		public int getMinutes()
		{
			return minutes;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "reviewInterval",
		name = "Interval",
		description = "How often a due card is served up",
		section = "review",
		position = 0
	)
	default ReviewInterval reviewInterval()
	{
		return ReviewInterval.FIVE_MINUTES;
	}

	@ConfigItem(
		keyName = "customMinutes",
		name = "Custom minutes",
		description = "Interval in minutes when Interval is set to Custom",
		section = "review",
		position = 1
	)
	default int customMinutes()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "pauseInCombat",
		name = "Pause during combat",
		description = "Hold new cards while you are fighting.",
		section = "review",
		position = 2
	)
	default boolean pauseInCombat()
	{
		return true;
	}

	// ---- Popup ----

	enum PopupCorner
	{
		TOP_LEFT("Top left"),
		TOP_RIGHT("Top right"),
		BOTTOM_LEFT("Bottom left"),
		BOTTOM_RIGHT("Bottom right");

		private final String label;

		PopupCorner(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "popupEnabled",
		name = "Show popup card",
		description = "Also show the current card as a small popup in a corner of the game screen",
		section = "popup",
		position = 0
	)
	default boolean popupEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "popupCorner",
		name = "Popup corner",
		description = "Which corner the popup card anchors to",
		section = "popup",
		position = 1
	)
	default PopupCorner popupCorner()
	{
		return PopupCorner.TOP_RIGHT;
	}


	// ---- Progress ----

	@ConfigItem(
		keyName = "levelUpBanner",
		name = "Level-up banner",
		description = "Show a celebratory banner in-game when your study skill levels up.",
		section = "progress",
		position = 1
	)
	default boolean levelUpBanner()
	{
		return true;
	}
}

package com.abyzz.ankiskiller;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Image;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * The plugin's home base: the lifetime study skill (level + XP bar), an Anki connection/deck
 * picker (with a setup guide when disconnected), and the current card with reveal, snooze, and
 * the four ease buttons. Snooze sits at the top of the card, deliberately far from the ease
 * buttons at the bottom so it can't be misclicked. All mutations funnel through refresh(), which
 * always lands on the Swing thread. Font sizes follow the configured UI scale.
 */
class AnkiSkillerPanel extends PluginPanel
{
	private static final String ANKICONNECT_CODE = "2055492159";

	// Base (100%) font sizes; multiplied by the configured scale in applyScale().
	private static final float LEVEL_SIZE = 22f;
	private static final float XP_SIZE = 13f;
	private static final float STATUS_SIZE = 13f;
	private static final float GUIDE_SIZE = 12f;
	private static final float CARD_TITLE_SIZE = 14f;
	private static final float CARD_TEXT_SIZE = 14f;
	private static final float BUTTON_SIZE = 12f;
	private static final int WRAP_WIDTH = 150;

	private final AnkiSkillerPlugin plugin;

	private final JLabel levelLabel = new JLabel();
	private final JProgressBar xpBar = new JProgressBar(0, 1000);
	private final JLabel xpLabel = new JLabel();

	private final JLabel statusLabel = new JLabel();
	private final JLabel guideLabel = new JLabel();
	private final JButton copyCodeButton = new JButton("Copy add-on code");
	private final JComboBox<String> deckBox = new JComboBox<>();
	private final JButton reloadButton = new JButton("Reload decks");

	private final JLabel cardTitle = new JLabel();
	private final JLabel cardText = new JLabel();
	private final JPanel cardImages = new JPanel();
	private final JButton revealButton = new JButton("Show answer");
	private final JButton snoozeButton = new JButton("Zzz");
	private final JPanel easeRow = new JPanel(new GridLayout(1, 4, 4, 0));
	private final JButton studyNowButton = new JButton("Study now");
	private final List<JButton> easeButtons = new ArrayList<>();

	AnkiSkillerPanel(AnkiSkillerPlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.add(buildSkillPanel());
		body.add(spacer());
		body.add(buildAnkiPanel());
		body.add(spacer());
		body.add(buildCardPanel());

		add(body, BorderLayout.NORTH);
		applyScale();
	}

	private Component spacer()
	{
		JPanel p = new JPanel();
		p.setPreferredSize(new Dimension(0, 10));
		p.setOpaque(false);
		return p;
	}

	private JPanel buildSkillPanel()
	{
		JPanel p = section("Study skill");

		levelLabel.setForeground(Color.WHITE);
		levelLabel.setAlignmentX(LEFT_ALIGNMENT);

		xpBar.setStringPainted(false);
		xpBar.setForeground(new Color(90, 170, 90));
		xpBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));

		xpLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		xpLabel.setAlignmentX(LEFT_ALIGNMENT);

		p.add(levelLabel);
		p.add(xpBar);
		p.add(xpLabel);
		return p;
	}

	private JPanel buildAnkiPanel()
	{
		JPanel p = section("Anki");

		statusLabel.setAlignmentX(LEFT_ALIGNMENT);

		guideLabel.setAlignmentX(LEFT_ALIGNMENT);
		guideLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		copyCodeButton.setAlignmentX(LEFT_ALIGNMENT);
		copyCodeButton.setToolTipText("Copy the AnkiConnect add-on code to paste into Anki");
		copyCodeButton.addActionListener(e -> {
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(ANKICONNECT_CODE), null);
			copyCodeButton.setText("Copied " + ANKICONNECT_CODE);
		});

		deckBox.setAlignmentX(LEFT_ALIGNMENT);
		deckBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		deckBox.setPrototypeDisplayValue("XXXXXXXXXXXXXXXX");
		deckBox.addActionListener(e -> {
			Object sel = deckBox.getSelectedItem();
			if (sel != null && deckBox.isEnabled())
			{
				plugin.setSelectedDeck(sel.toString());
			}
		});

		reloadButton.addActionListener(e -> reloadDecks());
		reloadButton.setAlignmentX(LEFT_ALIGNMENT);

		p.add(statusLabel);
		p.add(spacer());
		p.add(guideLabel);
		p.add(spacer());
		p.add(copyCodeButton);
		p.add(spacer());
		p.add(deckBox);
		p.add(spacer());
		p.add(reloadButton);
		return p;
	}

	private JPanel buildCardPanel()
	{
		JPanel p = section("Card");

		cardTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		// Title on the left, Snooze on the right: keeps snooze far from the ease buttons below.
		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.setAlignmentX(LEFT_ALIGNMENT);
		titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		snoozeButton.setMargin(new java.awt.Insets(1, 8, 1, 8));
		snoozeButton.setToolTipText("Snooze: dismiss this card and ask again next interval");
		snoozeButton.addActionListener(e -> plugin.snooze());
		titleRow.add(cardTitle, BorderLayout.WEST);
		titleRow.add(snoozeButton, BorderLayout.EAST);

		cardText.setAlignmentX(LEFT_ALIGNMENT);
		cardText.setForeground(Color.WHITE);
		cardText.setVerticalAlignment(SwingConstants.TOP);

		cardImages.setLayout(new BoxLayout(cardImages, BoxLayout.Y_AXIS));
		cardImages.setOpaque(false);
		cardImages.setAlignmentX(LEFT_ALIGNMENT);

		revealButton.setAlignmentX(LEFT_ALIGNMENT);
		revealButton.addActionListener(e -> plugin.revealAnswer());

		easeRow.setAlignmentX(LEFT_ALIGNMENT);
		easeRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		for (Ease ease : Ease.values())
		{
			JButton b = new JButton(ease.getLabel());
			b.setMargin(new java.awt.Insets(2, 2, 2, 2));
			b.addActionListener(e -> plugin.answer(ease));
			easeButtons.add(b);
			easeRow.add(b);
		}

		studyNowButton.setAlignmentX(LEFT_ALIGNMENT);
		studyNowButton.addActionListener(e ->
			new Thread(plugin::presentNextCard, "anki-study-now").start());

		p.add(titleRow);
		p.add(spacer());
		p.add(cardText);
		p.add(cardImages);
		p.add(spacer());
		p.add(revealButton);
		p.add(spacer());
		p.add(easeRow);
		p.add(spacer());
		p.add(studyNowButton);
		return p;
	}

	private JPanel section(String title)
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createTitledBorder(title),
			BorderFactory.createEmptyBorder(4, 4, 4, 4)));
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	// ---- scaling ----

	/** Re-derive every font from the configured UI scale. Safe to call on config change. */
	void applyScale()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::applyScale);
			return;
		}
		float s = (float) plugin.getConfig().uiScale().getFactor();
		levelLabel.setFont(levelLabel.getFont().deriveFont(Font.BOLD, LEVEL_SIZE * s));
		xpLabel.setFont(xpLabel.getFont().deriveFont(XP_SIZE * s));
		statusLabel.setFont(statusLabel.getFont().deriveFont(STATUS_SIZE * s));
		guideLabel.setFont(guideLabel.getFont().deriveFont(GUIDE_SIZE * s));
		cardTitle.setFont(cardTitle.getFont().deriveFont(Font.BOLD, CARD_TITLE_SIZE * s));
		cardText.setFont(cardText.getFont().deriveFont(CARD_TEXT_SIZE * s));
		deckBox.setFont(deckBox.getFont().deriveFont(BUTTON_SIZE * s));
		xpBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, Math.round(16 * s)));

		for (JButton b : allButtons())
		{
			b.setFont(b.getFont().deriveFont(BUTTON_SIZE * s));
		}
		// Snooze is an icon-only button showing the Zzz emoji, sized to the scale.
		javax.swing.ImageIcon zzz = Icons.zzz(Math.round(16 * s));
		if (zzz != null)
		{
			snoozeButton.setIcon(zzz);
			snoozeButton.setText("");
		}
		else
		{
			snoozeButton.setIcon(null);
			snoozeButton.setText("Zzz");
		}
		revalidate();
		repaint();
		refresh();
	}

	private List<JButton> allButtons()
	{
		List<JButton> all = new ArrayList<>(easeButtons);
		all.add(reloadButton);
		all.add(revealButton);
		all.add(snoozeButton);
		all.add(studyNowButton);
		all.add(copyCodeButton);
		return all;
	}

	// ---- data flow ----

	/** Reload deck list from Anki off-thread, then repopulate the combo on the EDT. */
	private void reloadDecks()
	{
		new Thread(() -> {
			try
			{
				List<String> decks = plugin.getAnki().deckNames();
				plugin.markAnkiReachable(true);
				SwingUtilities.invokeLater(() -> {
					String current = plugin.selectedDeck();
					deckBox.setEnabled(false);
					deckBox.setModel(new DefaultComboBoxModel<>(decks.toArray(new String[0])));
					if (current != null && decks.contains(current))
					{
						deckBox.setSelectedItem(current);
					}
					else if (!decks.isEmpty())
					{
						deckBox.setSelectedIndex(0);
						plugin.setSelectedDeck((String) deckBox.getSelectedItem());
					}
					deckBox.setEnabled(true);
					refresh();
				});
			}
			catch (Exception e)
			{
				plugin.markAnkiReachable(false);
			}
		}, "anki-deck-reload").start();
	}

	/** Called by the plugin after a card is answered. Flashes the level on a level-up. */
	void onAnswered(boolean leveledUp)
	{
		if (!leveledUp)
		{
			return;
		}
		SwingUtilities.invokeLater(() -> {
			int lvl = plugin.getProgress().currentLevel();
			levelLabel.setText("Level " + lvl + "  ⬆");
			levelLabel.setForeground(new Color(255, 200, 60));
			javax.swing.Timer timer = new javax.swing.Timer(2500, e -> {
				levelLabel.setForeground(Color.WHITE);
				refresh();
			});
			timer.setRepeats(false);
			timer.start();
		});
	}

	/** Repaint everything from current state. Always resolves on the EDT. */
	void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}

		SkillProgress prog = plugin.getProgress();
		int level = prog.currentLevel();
		levelLabel.setText("Level " + level);
		long into = prog.xpIntoLevel();
		long span = prog.xpSpanOfLevel();
		xpBar.setValue((int) Math.round(prog.progressToNext() * 1000));
		if (level >= SkillProgress.MAX_LEVEL)
		{
			xpLabel.setText(wrapped(String.format("%,d xp &bull; maxed", prog.getTotalXp())));
		}
		else
		{
			xpLabel.setText(wrapped(String.format("%,d / %,d to level %d &bull; %,d total",
				into, span, level + 1, prog.getTotalXp())));
		}

		boolean reachable = plugin.isAnkiReachable();
		statusLabel.setText(reachable ? "Connected to Anki" : "Anki not reachable");
		statusLabel.setForeground(reachable ? new Color(90, 170, 90) : new Color(200, 90, 90));

		// Show the setup steps only while disconnected.
		guideLabel.setVisible(!reachable);
		copyCodeButton.setVisible(!reachable);
		if (!reachable)
		{
			guideLabel.setText(wrapped(
				"To connect:<br>"
				+ "1. Open the Anki desktop app.<br>"
				+ "2. Tools &rarr; Add-ons &rarr; Get Add-ons.<br>"
				+ "3. Paste code <b>" + ANKICONNECT_CODE + "</b> and click OK.<br>"
				+ "4. Restart Anki, then Reload decks."));
			copyCodeButton.setText("Copy add-on code");
		}

		Card card = plugin.getCurrentCard();
		boolean hasCard = card != null;
		boolean revealed = hasCard && plugin.isAnswerRevealed();
		revealButton.setVisible(hasCard && !revealed);
		snoozeButton.setVisible(hasCard);
		setEaseEnabled(revealed);

		if (!hasCard)
		{
			cardTitle.setText("No card");
			cardText.setText("<html><i>Waiting for the next review.</i></html>");
		}
		else if (!revealed)
		{
			cardTitle.setText("Question");
			cardText.setText(html(card.getQuestion()));
		}
		else
		{
			cardTitle.setText("Answer");
			cardText.setText(revealedHtml(card.getQuestion(), card.getAnswer()));
		}

		cardImages.removeAll();
		if (hasCard)
		{
			int maxW = Math.round(170 * (float) plugin.getConfig().uiScale().getFactor());
			for (BufferedImage img : card.imagesFor(revealed))
			{
				cardImages.add(Box.createVerticalStrut(6));
				JLabel imageLabel = new JLabel(new ImageIcon(scaleToWidth(img, maxW)));
				imageLabel.setAlignmentX(LEFT_ALIGNMENT);
				cardImages.add(imageLabel);
			}
		}
		cardImages.revalidate();
		cardImages.repaint();
	}

	/** Scale an image down to fit the panel width, preserving aspect ratio. Never upscales. */
	private static Image scaleToWidth(BufferedImage img, int maxWidth)
	{
		if (img.getWidth() <= maxWidth)
		{
			return img;
		}
		int height = (int) Math.round(img.getHeight() * (maxWidth / (double) img.getWidth()));
		return img.getScaledInstance(maxWidth, height, Image.SCALE_SMOOTH);
	}

	private void setEaseEnabled(boolean enabled)
	{
		easeRow.setVisible(enabled);
		for (Component c : easeRow.getComponents())
		{
			c.setEnabled(enabled);
		}
	}

	// ---- html helpers ----

	private static String html(String text)
	{
		return wrapped(escape(text));
	}

	/** Shows the question (muted) above a divider, then the answer (white) below it. */
	private static String revealedHtml(String question, String answer)
	{
		return "<html><div style='width:" + WRAP_WIDTH + "px'>"
			+ "<span style='color:#9aa0a6'>" + escape(question) + "</span>"
			+ "<hr>"
			+ "<span style='color:#ffffff'>" + escape(answer) + "</span>"
			+ "</div></html>";
	}

	private static String wrapped(String safeText)
	{
		return "<html><div style='width:" + WRAP_WIDTH + "px'>" + safeText + "</div></html>";
	}

	private static String escape(String text)
	{
		return text == null ? "" : text
			.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.abyzz.ankiskiller;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "99 Studying",
	description = "Spaced-repetition flashcards while you skill, backed by Anki",
	tags = {"anki", "study", "flashcard", "spaced", "repetition", "afk"}
)
public class AnkiSkillerPlugin extends Plugin
{
	@Inject private AnkiSkillerConfig config;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private OverlayManager overlayManager;
	@Inject private AnkiConnect anki;
	@Inject private ScheduledExecutorService executor;
	@Inject private CardOverlay overlay;
	@Inject private LevelUpOverlay levelUpOverlay;
	@Inject private MouseManager mouseManager;
	@Inject private Client client;

	private NavigationButton navButton;
	private AnkiSkillerPanel panel;
	private SkillProgress progress;
	private ScheduledFuture<?> reviewTask;
	private MouseAdapter mouseListener;

	/** When the last level-up happened (for the flourish) and the level reached. */
	@Getter private volatile long levelUpAt;
	@Getter private volatile int levelUpLevel;

	/** Timestamp of the most recent combat hit involving the player, for the combat-pause. */
	private volatile long lastCombatMillis;
	private static final long COMBAT_TIMEOUT_MS = 8000;

	/** The card currently being reviewed, or null between reviews. Read from multiple threads. */
	@Getter private volatile Card currentCard;
	@Getter private volatile boolean answerRevealed;

	/** Cached Anki reachability so the UI thread never has to make a blocking network probe. */
	@Getter private volatile boolean ankiReachable;

	public void markAnkiReachable(boolean reachable)
	{
		this.ankiReachable = reachable;
		refreshUi();
	}

	@Provides
	AnkiSkillerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AnkiSkillerConfig.class);
	}

	@Override
	protected void startUp()
	{
		progress = new SkillProgress(configManager);
		panel = new AnkiSkillerPanel(this);

		navButton = NavigationButton.builder()
			.tooltip("99 Studying")
			.icon(makeIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlay.setPlugin(this);
		overlayManager.add(overlay);
		levelUpOverlay.setPlugin(this);
		overlayManager.add(levelUpOverlay);

		// Route clicks on the popup's buttons to the overlay; misses pass through untouched.
		mouseListener = new MouseAdapter()
		{
			@Override
			public MouseEvent mousePressed(MouseEvent e)
			{
				if (overlay.handleClick(e.getPoint()))
				{
					e.consume();
				}
				return e;
			}
		};
		mouseManager.registerMouseListener(mouseListener);

		panel.refresh();
		scheduleReviews();

		// Probe Anki once right away so the panel shows the correct status without waiting a full interval.
		executor.execute(() -> markAnkiReachable(anki.isReachable()));
	}

	@Override
	protected void shutDown()
	{
		cancelReviews();
		if (mouseListener != null)
		{
			mouseManager.unregisterMouseListener(mouseListener);
			mouseListener = null;
		}
		overlayManager.remove(overlay);
		overlayManager.remove(levelUpOverlay);
		clientToolbar.removeNavigation(navButton);
		currentCard = null;
		panel = null;
	}

	/** Small generated toolbar icon so we don't depend on a bundled image resource. */
	private static BufferedImage makeIcon()
	{
		BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(60, 130, 60));
		g.fillRoundRect(1, 1, 22, 22, 6, 6);
		g.setColor(Color.WHITE);
		g.setFont(new Font("SansSerif", Font.BOLD, 15));
		g.drawString("A", 7, 17);
		g.dispose();
		return img;
	}

	// ---- scheduling ----

	private int intervalMinutes()
	{
		AnkiSkillerConfig.ReviewInterval mode = config.reviewInterval();
		int minutes = mode == AnkiSkillerConfig.ReviewInterval.CUSTOM ? config.customMinutes() : mode.getMinutes();
		return Math.max(1, minutes);
	}

	private void scheduleReviews()
	{
		cancelReviews();
		long period = intervalMinutes() * 60L;
		reviewTask = executor.scheduleAtFixedRate(this::tick, period, period, TimeUnit.SECONDS);
	}

	private void cancelReviews()
	{
		if (reviewTask != null)
		{
			reviewTask.cancel(false);
			reviewTask = null;
		}
	}

	/**
	 * Fired by the scheduler on an executor thread. Wrapped so a stray exception can never
	 * escape: a repeating scheduled task that throws is silently cancelled forever, which
	 * would stop cards from ever appearing again.
	 */
	private void tick()
	{
		try
		{
			markAnkiReachable(anki.isReachable());
			// Don't stack up cards; if one is still on screen, wait for the player to answer it.
			if (currentCard != null)
			{
				return;
			}
			// Don't interrupt a fight; wait until the player is between kills.
			if (config.pauseInCombat() && inCombat())
			{
				return;
			}
			presentNextCard();
		}
		catch (Throwable t)
		{
			log.warn("Anki Skiller review tick failed", t);
		}
	}

	private boolean inCombat()
	{
		return System.currentTimeMillis() - lastCombatMillis < COMBAT_TIMEOUT_MS;
	}

	/** Runs on the client thread. Records combat whenever the player deals or takes a hit. */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		Actor target = event.getActor();
		if (target == local || target == local.getInteracting())
		{
			lastCombatMillis = System.currentTimeMillis();
		}
	}

	/** Pull the next due card for the selected deck and show it. Safe to call off-thread. */
	public void presentNextCard()
	{
		String deck = selectedDeck();
		if (deck == null || deck.isEmpty())
		{
			return;
		}
		try
		{
			List<Long> due = anki.findDueCards(deck);
			markAnkiReachable(true);
			if (due.isEmpty())
			{
				log.debug("No due cards in deck {}", deck);
				refreshUi();
				return;
			}
			Card card = anki.cardInfo(due.get(0));
			answerRevealed = false;
			currentCard = card;
			refreshUi();
		}
		catch (IOException e)
		{
			markAnkiReachable(false);
			log.debug("Could not fetch a card: {}", e.getMessage());
		}
		catch (Exception e)
		{
			log.warn("Unexpected error fetching a card", e);
		}
	}

	public void revealAnswer()
	{
		if (currentCard != null)
		{
			answerRevealed = true;
			refreshUi();
		}
	}

	/**
	 * Dismiss the current card without answering it. Because it was never reviewed it stays due
	 * in Anki, so it comes back at the next interval. The timer is reset so a full interval passes
	 * first, giving the player the whole snooze period before they're interrupted again.
	 */
	public void snooze()
	{
		currentCard = null;
		answerRevealed = false;
		scheduleReviews();
		refreshUi();
	}

	/** Submit an answer for the current card. Reviews it in Anki and awards XP. */
	public void answer(Ease ease)
	{
		final Card card = currentCard;
		if (card == null)
		{
			return;
		}
		executor.execute(() -> {
			try
			{
				anki.answerCard(card.getCardId(), ease.getValue());
			}
			catch (IOException e)
			{
				log.warn("Failed to submit answer to Anki: {}", e.getMessage());
				// Still award XP locally so a transient Anki hiccup doesn't eat the rep.
			}
			boolean leveledUp = progress.award(ease);
			if (leveledUp)
			{
				levelUpLevel = progress.currentLevel();
				levelUpAt = System.currentTimeMillis();
			}
			currentCard = null;
			answerRevealed = false;
			if (panel != null)
			{
				panel.onAnswered(leveledUp);
			}
			refreshUi();
		});
	}

	private void refreshUi()
	{
		if (panel != null)
		{
			panel.refresh();
		}
	}

	// ---- deck selection (persisted, player-scoped) ----

	public String selectedDeck()
	{
		return configManager.getConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_SELECTED_DECK);
	}

	public void setSelectedDeck(String deck)
	{
		configManager.setConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_SELECTED_DECK, deck);
	}

	// ---- accessors for UI ----

	public AnkiConnect getAnki()
	{
		return anki;
	}

	public SkillProgress getProgress()
	{
		return progress;
	}

	public AnkiSkillerConfig getConfig()
	{
		return config;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AnkiSkillerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("reviewInterval".equals(event.getKey()) || "customMinutes".equals(event.getKey()))
		{
			scheduleReviews();
		}
		if ("popupCorner".equals(event.getKey()) || "popupEnabled".equals(event.getKey()))
		{
			refreshUi();
		}
		if ("uiScale".equals(event.getKey()) && panel != null)
		{
			panel.applyScale();
		}
	}
}

package com.abyzz.ankiskiller;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * A single Anki card pulled from AnkiConnect, reduced to what the UI needs: the plain-text
 * question and answer plus any images pulled from the card's media.
 */
@Value
public class Card
{
	long cardId;
	String question;
	String answer;
	List<BufferedImage> questionImages;
	List<BufferedImage> answerImages;

	/** Images to show for the current face: the question's, plus the answer's once revealed. */
	public List<BufferedImage> imagesFor(boolean revealed)
	{
		if (!revealed)
		{
			return questionImages;
		}
		List<BufferedImage> all = new ArrayList<>(questionImages);
		all.addAll(answerImages);
		return all;
	}
}

package com.abyzz.ankiskiller;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import lombok.Setter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Optional in-game popup card anchored to a corner the player picks. Rendering only draws the
 * current card; click handling is routed in from the plugin's mouse listener via
 * {@link #handleClick(Point)}, hit-testing button rectangles the last render laid down. Never
 * covers the viewport centre and never returns "consumed" for a miss, so game clicks pass
 * through. Font size and width follow the configured UI scale.
 */
class CardOverlay extends Overlay
{
	private static final int BASE_WIDTH = 220;
	private static final int BASE_PAD = 8;
	private static final int BASE_BTN_H = 20;
	private static final float BASE_FONT = 12f;
	private static final Color BG = new Color(30, 30, 30, 220);
	private static final Color BORDER = new Color(90, 90, 90);

	@Setter
	private AnkiSkillerPlugin plugin;

	// Button rectangles from the most recent render, relative to the overlay origin.
	private Rectangle revealRect;
	private Rectangle snoozeRect;
	private final List<EaseButton> easeRects = new ArrayList<>();

	private static final class EaseButton
	{
		final Rectangle rect;
		final Ease ease;
		EaseButton(Rectangle rect, Ease ease)
		{
			this.rect = rect;
			this.ease = ease;
		}
	}

	CardOverlay()
	{
		setPosition(OverlayPosition.TOP_RIGHT);
		// Draw above game widgets so the card is never hidden behind an interface.
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		revealRect = null;
		snoozeRect = null;
		easeRects.clear();

		if (plugin == null || !plugin.getConfig().popupEnabled())
		{
			return null;
		}
		Card card = plugin.getCurrentCard();
		if (card == null)
		{
			return null;
		}

		setPosition(cornerToPosition(plugin.getConfig().popupCorner()));

		float s = (float) plugin.getConfig().uiScale().getFactor();
		g.setFont(g.getFont().deriveFont(BASE_FONT * s));
		FontMetrics fm = g.getFontMetrics();
		int line = fm.getHeight();
		int width = Math.round(BASE_WIDTH * s);
		int pad = Math.round(BASE_PAD * s);
		int btnH = Math.round(BASE_BTN_H * s);
		int gap = Math.round(4 * s);
		int topRowH = Math.max(line, btnH);

		boolean revealed = plugin.isAnswerRevealed();
		String heading = revealed ? "Answer" : "Question";
		String bodyText = revealed ? card.getAnswer() : card.getQuestion();

		List<String> lines = wrap(bodyText, fm, width - 2 * pad);
		int textBlock = line * lines.size();

		// Scale any card images to fit the popup width (capped in height so it stays compact).
		List<BufferedImage> images = card.imagesFor(revealed);
		List<int[]> imageDims = new ArrayList<>();
		int imgCap = Math.round(150 * s);
		int imagesBlock = 0;
		for (BufferedImage im : images)
		{
			double scale = Math.min(1.0, (width - 2 * pad) / (double) im.getWidth());
			int dw = (int) Math.round(im.getWidth() * scale);
			int dh = (int) Math.round(im.getHeight() * scale);
			if (dh > imgCap)
			{
				dw = (int) Math.round(dw * (imgCap / (double) dh));
				dh = imgCap;
			}
			imageDims.add(new int[]{dw, dh});
			imagesBlock += gap + dh;
		}

		int height = pad + topRowH + gap + textBlock + imagesBlock + gap + btnH + pad;

		g.setColor(BG);
		g.fillRect(0, 0, width, height);
		g.setColor(BORDER);
		g.drawRect(0, 0, width - 1, height - 1);

		// Top row: heading on the left, snooze (Zzz emoji) on the right, far from the ease buttons.
		g.setColor(new Color(154, 160, 166));
		g.drawString(heading, pad, pad + fm.getAscent());
		int iconSize = Math.max(8, btnH - Math.round(6 * s));
		int snoozeW = iconSize + Math.round(10 * s);
		snoozeRect = new Rectangle(width - pad - snoozeW, pad, snoozeW, btnH);
		g.setColor(new Color(60, 60, 60));
		g.fillRect(snoozeRect.x, snoozeRect.y, snoozeRect.width, snoozeRect.height);
		g.setColor(BORDER);
		g.drawRect(snoozeRect.x, snoozeRect.y, snoozeRect.width, snoozeRect.height);
		if (Icons.ZZZ != null)
		{
			int ix = snoozeRect.x + (snoozeRect.width - iconSize) / 2;
			int iy = snoozeRect.y + (snoozeRect.height - iconSize) / 2;
			g.drawImage(Icons.ZZZ, ix, iy, iconSize, iconSize, null);
		}
		else
		{
			drawButton(g, snoozeRect, "Zzz", new Color(60, 60, 60), fm);
		}

		// Body
		g.setColor(Color.WHITE);
		int y = pad + topRowH + gap + fm.getAscent();
		for (String l : lines)
		{
			g.drawString(l, pad, y);
			y += line;
		}

		// Card images below the text
		int iy = pad + topRowH + gap + textBlock;
		for (int k = 0; k < images.size(); k++)
		{
			iy += gap;
			int[] dim = imageDims.get(k);
			g.drawImage(images.get(k), pad, iy, dim[0], dim[1], null);
			iy += dim[1];
		}

		// Bottom row
		int by = height - pad - btnH;
		if (!revealed)
		{
			revealRect = new Rectangle(pad, by, width - 2 * pad, btnH);
			drawButton(g, revealRect, "Show answer", new Color(60, 60, 60), fm);
		}
		else
		{
			int bw = (width - 2 * pad - 3 * gap) / 4;
			int bx = pad;
			for (Ease ease : Ease.values())
			{
				Rectangle r = new Rectangle(bx, by, bw, btnH);
				drawButton(g, r, ease.getLabel(), new Color(55, 70, 55), fm);
				easeRects.add(new EaseButton(r, ease));
				bx += bw + gap;
			}
		}

		return new Dimension(width, height);
	}

	private void drawButton(Graphics2D g, Rectangle r, String label, Color fill, FontMetrics fm)
	{
		g.setColor(fill);
		g.fillRect(r.x, r.y, r.width, r.height);
		g.setColor(BORDER);
		g.drawRect(r.x, r.y, r.width, r.height);
		g.setColor(Color.WHITE);
		int tx = r.x + Math.max(2, (r.width - fm.stringWidth(label)) / 2);
		int ty = r.y + (r.height + fm.getAscent()) / 2 - 2;
		g.drawString(label, tx, ty);
	}

	/**
	 * Route a canvas-space click. Returns true only if it landed on one of our buttons,
	 * so the caller consumes the event; any miss returns false and the click is left alone.
	 */
	boolean handleClick(Point canvasPoint)
	{
		if (plugin == null || !plugin.getConfig().popupEnabled() || plugin.getCurrentCard() == null)
		{
			return false;
		}
		Rectangle bounds = getBounds();
		if (bounds == null)
		{
			return false;
		}
		Point local = new Point(canvasPoint.x - bounds.x, canvasPoint.y - bounds.y);

		// Snooze is available in both states, at the top-right.
		if (snoozeRect != null && snoozeRect.contains(local))
		{
			plugin.snooze();
			return true;
		}
		if (!plugin.isAnswerRevealed())
		{
			if (revealRect != null && revealRect.contains(local))
			{
				plugin.revealAnswer();
				return true;
			}
			return false;
		}
		for (EaseButton b : easeRects)
		{
			if (b.rect.contains(local))
			{
				plugin.answer(b.ease);
				return true;
			}
		}
		return false;
	}

	private static OverlayPosition cornerToPosition(AnkiSkillerConfig.PopupCorner corner)
	{
		switch (corner)
		{
			case TOP_LEFT:
				return OverlayPosition.TOP_LEFT;
			case BOTTOM_LEFT:
				return OverlayPosition.BOTTOM_LEFT;
			case BOTTOM_RIGHT:
				return OverlayPosition.BOTTOM_RIGHT;
			case TOP_RIGHT:
			default:
				return OverlayPosition.TOP_RIGHT;
		}
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			lines.add("");
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String trial = line.length() == 0 ? word : line + " " + word;
			Rectangle2D b = fm.getStringBounds(trial, null);
			if (b.getWidth() > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(trial);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		// Keep the popup compact; cap lines.
		if (lines.size() > 10)
		{
			lines = new ArrayList<>(lines.subList(0, 10));
			lines.set(9, lines.get(9) + " ...");
		}
		return lines;
	}
}

package com.abyzz.ankiskiller;

/**
 * The four Anki answer buttons. The ease value is exactly what AnkiConnect's
 * answerCards action expects (1 = Again .. 4 = Easy). Base XP mirrors OSRS:
 * different "actions" pay differently, and even a failed rep pays a little.
 */
public enum Ease
{
	AGAIN(1, "Again", 2),
	HARD(2, "Hard", 6),
	GOOD(3, "Good", 9),
	EASY(4, "Easy", 15);

	private final int value;
	private final String label;
	private final int baseXp;

	Ease(int value, String label, int baseXp)
	{
		this.value = value;
		this.label = label;
		this.baseXp = baseXp;
	}

	public int getValue()
	{
		return value;
	}

	public String getLabel()
	{
		return label;
	}

	public int getBaseXp()
	{
		return baseXp;
	}
}

package com.abyzz.ankiskiller;

import java.awt.Image;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;

/**
 * Bundled image assets. The Zzz icon is the 💤 sleeping-symbol emoji (RuneLite's Swing font
 * can't render emoji as text, so we ship it as an image and scale it per UI scale).
 */
final class Icons
{
	static final BufferedImage ZZZ = loadSafe("/com/abyzz/ankiskiller/zzz.png");

	private Icons()
	{
	}

	private static BufferedImage loadSafe(String path)
	{
		try
		{
			return ImageUtil.loadImageResource(AnkiSkillerPlugin.class, path);
		}
		catch (Throwable t)
		{
			// Missing/broken asset must never crash the plugin; callers fall back gracefully.
			return null;
		}
	}

	/** The Zzz emoji scaled to a square of the given pixel size, or null if the asset is missing. */
	static ImageIcon zzz(int size)
	{
		if (ZZZ == null || size <= 0)
		{
			return null;
		}
		return new ImageIcon(ZZZ.getScaledInstance(size, size, Image.SCALE_SMOOTH));
	}
}

package com.abyzz.ankiskiller;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import lombok.Setter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A brief celebratory banner shown in-game when the study skill levels up. Reads the plugin's
 * last level-up timestamp and fades out over a few seconds, then stops drawing. Only renders
 * in-game (overlays draw over the game world); the panel handles the logged-out flourish.
 */
class LevelUpOverlay extends Overlay
{
	private static final long DURATION_MS = 4000;
	private static final Color GOLD = new Color(255, 200, 60);

	@Setter
	private AnkiSkillerPlugin plugin;

	LevelUpOverlay()
	{
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (plugin == null || !plugin.getConfig().levelUpBanner())
		{
			return null;
		}
		long since = System.currentTimeMillis() - plugin.getLevelUpAt();
		if (since < 0 || since > DURATION_MS)
		{
			return null;
		}

		float alpha = Math.max(0f, Math.min(1f, 1f - (since / (float) DURATION_MS)));
		float s = (float) plugin.getConfig().uiScale().getFactor();

		String line1 = "Study skill up!";
		String line2 = "You reached level " + plugin.getLevelUpLevel();

		Font f1 = g.getFont().deriveFont(Font.BOLD, 18f * s);
		Font f2 = g.getFont().deriveFont(14f * s);
		FontMetrics fm1 = g.getFontMetrics(f1);
		FontMetrics fm2 = g.getFontMetrics(f2);

		int pad = Math.round(10 * s);
		int gap = Math.round(4 * s);
		int textW = Math.max(fm1.stringWidth(line1), fm2.stringWidth(line2));
		int width = textW + 2 * pad;
		int height = pad + fm1.getHeight() + gap + fm2.getHeight() + pad;

		java.awt.Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

		g.setColor(new Color(20, 20, 20, 220));
		g.fillRect(0, 0, width, height);
		g.setColor(GOLD);
		g.drawRect(0, 0, width - 1, height - 1);

		g.setFont(f1);
		int y = pad + fm1.getAscent();
		g.drawString(line1, (width - fm1.stringWidth(line1)) / 2, y);

		g.setFont(f2);
		y += gap + fm2.getAscent();
		g.setColor(Color.WHITE);
		g.drawString(line2, (width - fm2.stringWidth(line2)) / 2, y);

		g.setComposite(old);
		return new Dimension(width, height);
	}
}

package com.abyzz.ankiskiller;

import lombok.Getter;
import net.runelite.client.config.ConfigManager;

/**
 * The player's lifetime study "skill". XP belongs to the player, not the deck,
 * so swapping decks never resets progress. Uses the exact OSRS experience curve,
 * levels 1 to 99, so a level here means the same grind a real skill would.
 */
public class SkillProgress
{
	/**
	 * Canonical OSRS total-XP thresholds. Index 0 = level 1 (0 xp) .. index 98 = level 99.
	 * Generated from xp(L) = floor( (1/4) * sum_{x=1}^{L-1} floor(x + 300 * 2^(x/7)) ).
	 * Hardcoded so we never recompute the sum at runtime.
	 */
	private static final int[] XP_TABLE = {
		0, 83, 174, 276, 388, 512, 650, 801, 969, 1154,
		1358, 1584, 1833, 2107, 2411, 2746, 3115, 3523, 3973, 4470,
		5018, 5624, 6291, 7028, 7842, 8740, 9730, 10824, 12031, 13363,
		14833, 16456, 18247, 20224, 22406, 24815, 27473, 30408, 33648, 37224,
		41171, 45529, 50339, 55649, 61512, 67983, 75127, 83014, 91721, 101333,
		111945, 123660, 136594, 150872, 166636, 184040, 203254, 224466, 247886, 273742,
		302288, 333804, 368599, 407015, 449428, 496254, 547953, 605032, 668051, 737627,
		814445, 899257, 992895, 1096278, 1210421, 1336443, 1475581, 1629200, 1798808, 1986068,
		2192818, 2421087, 2673114, 2951373, 3258594, 3597792, 3972294, 4385776, 4842295, 5346332,
		5902831, 6517253, 7195629, 7944614, 8771558, 9684577, 10692629, 11805606, 13034431
	};

	public static final int MAX_LEVEL = 99;
	public static final long MAX_XP = XP_TABLE[MAX_LEVEL - 1];

	// Each level pays a little more per card so higher levels don't feel as brutal:
	// +4% of the base XP per level above 1 (level 20 ~ 1.76x, level 99 ~ 4.9x).
	private static final double XP_LEVEL_BONUS = 0.04;

	private final ConfigManager configManager;

	@Getter
	private long totalXp;
	@Getter
	private long cardsAnswered;

	public SkillProgress(ConfigManager configManager)
	{
		this.configManager = configManager;
		load();
	}

	private void load()
	{
		Long xp = configManager.getConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_TOTAL_XP, Long.class);
		Long answered = configManager.getConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_CARDS_ANSWERED, Long.class);
		this.totalXp = xp == null ? 0 : xp;
		this.cardsAnswered = answered == null ? 0 : answered;
	}

	/**
	 * Award XP for one answered card and persist. Returns true if the answer crossed
	 * a level boundary (caller fires the level-up flourish).
	 */
	public boolean award(Ease ease)
	{
		int before = currentLevel();
		double multiplier = 1.0 + XP_LEVEL_BONUS * (before - 1);
		long gain = Math.max(ease.getBaseXp(), Math.round(ease.getBaseXp() * multiplier));
		totalXp = Math.min(MAX_XP, totalXp + gain);
		cardsAnswered++;
		persist();
		return currentLevel() > before;
	}

	private void persist()
	{
		configManager.setConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_TOTAL_XP, totalXp);
		configManager.setConfiguration(AnkiSkillerConfig.GROUP, AnkiSkillerConfig.KEY_CARDS_ANSWERED, cardsAnswered);
	}

	public int currentLevel()
	{
		return levelForXp(totalXp);
	}

	public static int levelForXp(long xp)
	{
		int level = 1;
		for (int i = 0; i < XP_TABLE.length; i++)
		{
			if (xp >= XP_TABLE[i])
			{
				level = i + 1;
			}
			else
			{
				break;
			}
		}
		return level;
	}

	public static long xpForLevel(int level)
	{
		if (level <= 1)
		{
			return 0;
		}
		if (level > MAX_LEVEL)
		{
			return MAX_XP;
		}
		return XP_TABLE[level - 1];
	}

	/** XP into the current level, toward the next. */
	public long xpIntoLevel()
	{
		return totalXp - xpForLevel(currentLevel());
	}

	/** XP span of the current level (current level threshold to next). 0 at level 99. */
	public long xpSpanOfLevel()
	{
		int level = currentLevel();
		if (level >= MAX_LEVEL)
		{
			return 0;
		}
		return xpForLevel(level + 1) - xpForLevel(level);
	}

	/** Progress through the current level, 0.0 to 1.0. Returns 1.0 at level 99. */
	public double progressToNext()
	{
		long span = xpSpanOfLevel();
		if (span <= 0)
		{
			return 1.0;
		}
		return Math.min(1.0, (double) xpIntoLevel() / span);
	}
}

